import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh } = ctx.THREE;

  // --- Group ---
  const group = new Group();

  // --- Plane with texture ---
  const planeWidth = 1.6; // aspect 512/320 ≈ 1.6
  const planeHeight = 1.0;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    color: config.colors?.surface || '#0b0b10',
    transparent: true,
  });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load texture
  let texture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Text "Features 1" ---
  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textContent.find(item => item.role === 'headline');
  const textStr = headlineItem ? headlineItem.text : 'Features 1';
  const fontSize = headlineItem?.typography?.fontSize ?? 39;

  const textOpts = {
    fontSize: fontSize,
    color: config.colors?.paper || '#e8ecf2',
    align: 'center',
  };
  const textMesh = ctx.fontAtlas.createText(textStr, textOpts);
  // Scale text to fit card width (approx 1.6 units) – adjust as needed
  const textScale = 0.8; // arbitrary fit
  textMesh.scale.set(textScale, textScale, textScale);
  textMesh.position.set(0, 0, 0.01); // slightly in front of plane
  group.add(textMesh);

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
    // Dispose text resources (traverse)
    textMesh.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material?.dispose();
        }
      }
    });
  };

  // No handlers
  group.userData.handlers = {};

  return group;
}
